mapper.select:
  SELECT 
	CASE 
  		/*次日*/
  		WHEN TEMP_INFO.EDAYS = 1 THEN 'A'
  		/*2日-7日*/
  		WHEN TEMP_INFO.EDAYS BETWEEN 2 AND 7 THEN 'B'
  		/*7日-30日*/
  		WHEN TEMP_INFO.EDAYS BETWEEN 8 AND 30 THEN 'C'
  		/*31日-90日*/
  		WHEN TEMP_INFO.EDAYS BETWEEN 31 AND 90 THEN 'D'
  		/*91日-1年*/
  		WHEN TEMP_INFO.EDAYS BETWEEN 91 AND 365 THEN 'E'
  		/*1年-5年*/
  		WHEN TEMP_INFO.EDAYS BETWEEN 366 AND 1825 THEN 'F'
  		/*5年-10年*/
  		WHEN TEMP_INFO.EDAYS BETWEEN 1826 AND 3650 THEN 'G'
  		/*10年以上*/
 		 WHEN TEMP_INFO.EDAYS > 3650 THEN 'H'
 		 /*逾期限*/
  		WHEN TEMP_INFO.EDAYS <= 0 THEN 'I' 
  		/*逾未定期*/
  		ELSE 'J'
	END AS eDays,
	TEMP_INFO.ASSETVALUE_A AS prinamt,
	TEMP_INFO.ASSET_ID AS attributeId,
	TEMP_INFO.ASSET_TYPE2 AS attributeType
	FROM
	(
		SELECT BASE.MDATE - #{endDate,jdbcType=DATE} EDAYS, BASE.ASSET_ID, INFO.ASSET_TYPE2, POSITION.ASSETVALUE_A 
		FROM CHB_MONTH_ASSET_POSITION POSITION 
    	LEFT JOIN (SELECT DISTINCT ASSET_ID, VALUE_DATE, STATUS, MDATE FROM CHB_ASSETS_BASIS_DATA) BASE
		ON BASE.ASSET_ID = POSITION.ASSET_CODE
		LEFT JOIN CHB_ASSET_INFO INFO
		ON BASE.ASSET_ID = INFO.ASSET_CODE
		WHERE POSITION.ENDDATE = #{endDate,jdbcType=DATE}
		AND BASE.VALUE_DATE = #{endDate,jdbcType=DATE}
		AND BASE.STATUS IN ('E', 'M')
		AND INFO.STATUS IN ('E', 'M')
		AND POSITION.ASSETVALUE_A  IS NOT NULL
	) TEMP_INFO
